def pre(n):
    return 0 <= n <= 250

def post(n, result):
    # Independent reference: n > 1 and no divisor d with 2 <= d < n.
    # For n <= 250, any composite n has a proper divisor <= 15 (since 16*16 = 256 > 250),
    # so checking d in 2..15 is sufficient.
    expected = n > 1
    for d in range(2, 16):
        if d < n and n % d == 0:
            expected = False
    return result == expected
